package com.openfoodfacts.mcp;

import org.springframework.stereotype.Service;
import java.util.*;
import java.util.regex.*;

@Service
public class NutritionService {
    private static final List<String> ALLERGENS=List.of("peanut","peanuts","arachis","milk","lactose","dairy","casein","whey","egg","eggs","ovalbumin","soy","soya","soybean","wheat","gluten","tree nuts","almond","almonds","hazelnut","hazelnuts","cashew","walnut","walnuts","pistachio","fish","cod","salmon","tuna","shellfish","shrimp","crab","lobster","prawn","sesame","celery","mustard","lupin","lupine","molluscs","squid","octopus","sulphites","sulfites","sulphur dioxide");
    private static List<String> contains(String text,List<String> words){String s=text.toLowerCase(Locale.ROOT); return words.stream().filter(s::contains).toList();}
    private static Map<String,Object> map(Object... kv){var m=new LinkedHashMap<String,Object>();for(int i=0;i<kv.length;i+=2)m.put((String)kv[i],kv[i+1]);return m;}
    private static String level(String n,Double v){if(v==null)return "unknown"; double low=switch(n){case"fat"->3;case"saturated_fat"->1.5;case"sugars"->5;case"salt"->.3;case"sodium"->.1;default->Double.NaN;};double high=switch(n){case"fat"->17.5;case"saturated_fat"->5;case"sugars"->22.5;case"salt"->1.5;case"sodium"->.6;default->Double.NaN;};return Double.isNaN(low)?"unknown":v<=low?"low":v>=high?"high":"moderate";}
    public Map<String,Object> nutrition(Product p){var ns=new ArrayList<Map<String,Object>>();for(String[] x:new String[][]{{"Fat","fat_100g","g"},{"Saturated Fat","saturated_fat_100g","g"},{"Sugars","sugars_100g","g"},{"Salt","salt_100g","g"},{"Protein","proteins_100g","g"},{"Fiber","fiber_100g","g"},{"Carbohydrates","carbohydrates_100g","g"}}){Double v=p.nutrient(x[1]);ns.add(map("name",x[0],"value_per_100g",v,"unit",x[2],"level",level(x[1].replace("_100g",""),v)));}
        var highlights=new ArrayList<String>();String grade=p.nutrition_grades();if(!grade.isBlank()){String g=grade.toUpperCase();if(g.equals("A")||g.equals("B"))highlights.add("Good Nutri-Score: "+g);if(g.equals("D")||g.equals("E"))highlights.add("Poor Nutri-Score: "+g+" — consider healthier alternatives");}if(Objects.equals(p.nova_group(),4))highlights.add("NOVA Group 4: Ultra-processed food");if(Objects.equals(p.nova_group(),1))highlights.add("NOVA Group 1: Unprocessed or minimally processed food");for(var n:ns)if("high".equals(n.get("level")))highlights.add("High "+n.get("name")+": "+n.get("value_per_100g")+n.get("unit")+" per 100g");
        return map("nutriscore_grade",grade.isBlank()?"unknown":grade,"nova_group",p.nova_group(),"ecoscore_grade",p.ecoscore_grade().isBlank()?"unknown":p.ecoscore_grade(),"calories_per_100g",p.nutrient("energy_kcal_100g"),"key_nutrients",ns,"health_highlights",highlights);}
    public Map<String,Object> dietary(Product p){String i=p.ingredients_text().toLowerCase(),l=p.labels().toLowerCase();var meat=contains(i,List.of("meat","beef","pork","chicken","lamb","turkey","duck","bacon","ham","sausage","salami","pepperoni","gelatin","gelatine","lard","tallow","suet","anchovy","anchovies","fish","shrimp","crab","lobster","prawn","squid","octopus"));var dairy=contains(i,List.of("milk","cheese","butter","cream","yogurt","yoghurt","whey","casein","lactose","ghee","curd"));var egg=contains(i,List.of("egg","eggs","ovalbumin","albumin","lysozyme"));var gluten=contains(i,List.of("wheat","barley","rye","oats","spelt","kamut","triticale","gluten"));var notes=new ArrayList<String>();boolean absent=i.isBlank()&&l.isBlank();if(absent)notes.add("No ingredient information available. Cannot determine dietary suitability. Please verify the actual packaging.");else{if(!meat.isEmpty())notes.add("Contains non-vegetarian ingredients: "+String.join(", ",meat));if(!dairy.isEmpty()||!egg.isEmpty()){var x=new ArrayList<>(dairy);x.addAll(egg);notes.add("Contains non-vegan ingredients: "+String.join(", ",x));}if(!gluten.isEmpty())notes.add("May contain gluten: "+String.join(", ",gluten));if(!dairy.isEmpty())notes.add("Contains dairy: "+String.join(", ",dairy));notes.add("This analysis is based on ingredient text parsing and may not be fully accurate. Always verify the actual product packaging for definitive dietary information.");}
        Boolean vegetarian=absent?null:(meat.isEmpty()||l.contains("vegetarian"));if(!meat.isEmpty())vegetarian=false;
        Boolean vegan=absent?null:(meat.isEmpty()&&dairy.isEmpty()&&egg.isEmpty()||l.contains("vegan"));if(!dairy.isEmpty()||!egg.isEmpty())vegan=false;
        Boolean glutenFree=absent?null:(gluten.isEmpty()||l.contains("gluten-free")||l.contains("gluten free"));if(!gluten.isEmpty())glutenFree=false;
        return map("is_vegetarian",vegetarian,"is_vegan",vegan,"is_gluten_free",glutenFree,"is_dairy_free",absent?null:dairy.isEmpty(),"confidence",!absent&&i.length()>20?"medium":"low","notes",notes);}
    public Map<String,Object> allergens(Product p){var detected=new ArrayList<String>();var traces=new ArrayList<String>();for(String x:p.allergens().toLowerCase(Locale.ROOT).split(","))if(!x.isBlank())detected.add(x.trim().replaceFirst("^en:",""));for(String x:p.traces().toLowerCase(Locale.ROOT).split(","))if(!x.isBlank())traces.add(x.trim().replaceFirst("^en:",""));for(String x:contains(p.ingredients_text(),ALLERGENS))if(detected.stream().noneMatch(a->a.contains(x)))detected.add(x);return map("detected_allergens",new ArrayList<>(new LinkedHashSet<>(detected)),"potential_traces",new ArrayList<>(new LinkedHashSet<>(traces)),"confidence",p.ingredients_text().length()>20||!p.allergens().isBlank()?"medium":"low","disclaimer","This allergen report is based on data from Open Food Facts and ingredient text parsing. It may not capture all allergens. ALWAYS verify the actual product packaging, especially for severe allergies. Manufacturers may change formulations without notice.");}
    public Map<String,Object> ingredients(Product p){String text=p.ingredients_text();var additives=new ArrayList<String>();Matcher m=Pattern.compile("\\b(?:E\\s?\\d{3,4}[a-z]?|INS\\s?\\d{3,4}[a-z]?)\\b",Pattern.CASE_INSENSITIVE).matcher(text);while(m.find())additives.add(m.group());var names=List.of("maltodextrin","emulsifier","stabilizer","stabiliser","preservative","antioxidant","colour","color","flavour","flavor","sweetener","thickener","acidity regulator","raising agent","modified starch","mono- and diglycerides","lecithin","xanthan gum","carrageenan","aspartame","sucralose","acesulfame");additives.addAll(contains(text,names));var allergens=contains(text,ALLERGENS);var explanation=new ArrayList<String>();if(text.isBlank())explanation.add("No ingredient information available for this product.");else{explanation.add("This product lists the following ingredients: "+text);explanation.add(additives.isEmpty()?"No common additives or E-numbers were detected in the ingredient list.":"Identified additives and processing aids: "+String.join(", ",new LinkedHashSet<>(additives)));if(!allergens.isEmpty())explanation.add("Potential allergens detected in ingredients: "+String.join(", ",new LinkedHashSet<>(allergens)));}return map("ingredients_text",text,"identified_additives",new ArrayList<>(new LinkedHashSet<>(additives)),"identified_allergens",new ArrayList<>(new LinkedHashSet<>(allergens)),"explanation",explanation);}
    public Map<String,Object> comparison(List<Product> ps,String criteria){var rows=new ArrayList<Map<String,Object>>();for(Product p:ps)rows.add(map("barcode",p.barcode(),"product_name",p.product_name(),"nutriscore_grade",p.nutrition_grades().isBlank()?"unknown":p.nutrition_grades(),"nova_group",p.nova_group(),"calories_per_100g",p.nutrient("energy_kcal_100g"),"sugar_per_100g",p.nutrient("sugars_100g"),"fat_per_100g",p.nutrient("fat_100g"),"protein_per_100g",p.nutrient("proteins_100g"),"salt_per_100g",p.nutrient("salt_100g")));
        String key=switch(criteria){case "sugar", "sugars"->"sugar_per_100g";case "fat"->"fat_per_100g";case "protein"->"protein_per_100g";case "calories"->"calories_per_100g";default->"nutriscore_grade";};
        Comparator<Map<String,Object>> cmp;
        if(key.equals("nutriscore_grade")) cmp=Comparator.comparingInt(r->{int i=List.of("a","b","c","d","e").indexOf(String.valueOf(r.get(key)).toLowerCase(Locale.ROOT));return i<0?6:i;});
        else if(criteria.equals("protein")) cmp=Comparator.comparingDouble(r->-(r.get(key) instanceof Number n?n.doubleValue():0));
        else cmp=Comparator.comparingDouble(r->r.get(key) instanceof Number n?n.doubleValue():999);
        var best=rows.stream().min(cmp).orElse(null); String rec;
        if(best==null) rec=switch(criteria){case "sugar","sugars"->"Unable to compare sugar content.";case "fat"->"Unable to compare fat content.";case "protein"->"Unable to compare protein content.";case "calories"->"Unable to compare calories.";default->"Unable to determine the best product.";};
        else {Object value=best.get(key);String amount=value==null?"unknown":value instanceof Double d && d==Math.rint(d)?Long.toString(d.longValue()):value.toString();String name=String.valueOf(best.get("product_name"));rec=switch(criteria){case "sugar","sugars"->name+" has the lowest sugar content at "+amount+"g per 100g.";case "fat"->name+" has the lowest fat content at "+amount+"g per 100g.";case "protein"->name+" has the highest protein content at "+amount+"g per 100g.";case "calories"->name+" has the lowest calories at "+amount+" kcal per 100g.";default->name+" has the best overall Nutri-Score: "+amount.toUpperCase(Locale.ROOT)+".";};}
        return map("products",rows,"recommendation",rec,"criteria_used",criteria);}
}
